{"Channel": {"name": "develop-davidgarcia-SummarizeForce", "channelID": "ch-force-6723be"}, "Message": {"User": {"userId": "eid_1f678d18", "timestamp": "2026-11-06T22:48:00", "text": "That's a bit limiting. In fast-paced environments, integration is key. How about the quality of their summaries? Do they capture the essence of discussions well?", "utterranceID": "20261220-5-7c7c2"}, "Reactions": []}, "ThreadReplies": [], "id": "20261220-5-7c7c2"}
