{"Channel": {"name": "develop-davidtaylor-VizForce", "channelID": "ch-force-4e46da"}, "Message": {"User": {"userId": "eid_0c373165", "timestamp": "2026-05-05T06:07:00", "text": "Hey @eid_104b8b57, does the lack of customization affect its usability for larger projects?", "utterranceID": "20260718-3-f0fc9"}, "Reactions": []}, "ThreadReplies": [], "id": "20260718-3-f0fc9"}
