{"Channel": {"name": "bug-iansmith-ContextForce", "channelID": "ch-force-5ff1be"}, "Message": {"User": {"userId": "eid_92c62291", "timestamp": "2027-01-09T17:44:00", "text": "Great news, George! Can you explain what was causing the issue?", "utterranceID": "20270109-1-53d15"}, "Reactions": []}, "ThreadReplies": [], "id": "20270109-1-53d15"}
