{"Channel": {"name": "bug-bobmiller-MonitorForce", "channelID": "ch-force-c6eeee"}, "Message": {"User": {"userId": "eid_44c67741", "timestamp": "2026-10-08T13:29:00", "text": "Great news, @eid_9de52b6e! Can you explain what caused the issue?", "utterranceID": "20261008-1-4c704"}, "Reactions": []}, "ThreadReplies": [], "id": "20261008-1-4c704"}
