{"Channel": {"name": "bug-bobdavis-PersonalizeForce", "channelID": "ch-force-cdb98a"}, "Message": {"User": {"userId": "eid_eed289d3", "timestamp": "2026-11-11T14:07:00", "text": "Will do! Thanks for coordinating, @eid_e0273792. 🙌", "utterranceID": "20261111-8-d28ab"}, "Reactions": []}, "ThreadReplies": [], "id": "20261111-8-d28ab"}
