{"Channel": {"name": "develop-emmamartinez-ProposalForce", "channelID": "ch-force-888914"}, "Message": {"User": {"userId": "eid_8b67a68f", "timestamp": "2027-03-27T02:53:00", "text": "Yes, @Charlie Miller, I've added both unit and integration tests to ensure everything works smoothly. Let me know if you spot anything off!", "utterranceID": "20270329-3-a7ad6"}, "Reactions": []}, "ThreadReplies": [], "id": "20270329-3-a7ad6"}
