{"Channel": {"name": "bug-alicedavis-ConnectForce", "channelID": "ch-force-e0f240"}, "Message": {"User": {"userId": "eid_71071933", "timestamp": "2026-08-19T15:52:00", "text": "Thanks for the update, Fiona. Glad to hear it's just a configuration issue.", "utterranceID": "20260819-7-2c3e6"}, "Reactions": []}, "ThreadReplies": [], "id": "20260819-7-2c3e6"}
