{"Channel": {"name": "bug-alicetaylor-MonitorForce", "channelID": "ch-force-7ef125"}, "Message": {"User": {"userId": "eid_5b9ab912", "timestamp": "2026-06-18T12:43:00", "text": "Hi team, several customers are reporting issues with MonitorForce that we need to address ASAP. Let's go through them one by one. 🚀", "utterranceID": "20260618-0-314f0"}, "Reactions": []}, "ThreadReplies": [], "id": "20260618-0-314f0"}
