{"Channel": {"name": "bug-juliagarcia-PitchForce", "channelID": "ch-force-f603c3"}, "Message": {"User": {"userId": "eid_e4d35074", "timestamp": "2027-01-31T15:57:00", "text": "Same here, I'll update once the API security is tightened. 🔐", "utterranceID": "20270131-9-537c0"}, "Reactions": []}, "ThreadReplies": [], "id": "20270131-9-537c0"}
