{"Channel": {"name": "bug-iansmith-FeedbackForce", "channelID": "ch-force-0a044a"}, "Message": {"User": {"userId": "slack_admin_bot", "timestamp": "2026-12-05T12:25:00", "text": "@eid_6f719d21 created this channel on 2026-12-05 12:25:00. This is the very beginning of the bug-iansmith-FeedbackForce channel.", "utterranceID": "20261205-0-a68a9"}, "Reactions": []}, "ThreadReplies": [], "id": "20261205-0-a68a9"}
