{"Channel": {"name": "bug-iansmith-ContextForce", "channelID": "ch-force-5ff1be"}, "Message": {"User": {"userId": "eid_5782059f", "timestamp": "2027-01-14T10:19:00", "text": "Will do! If anyone has insights on similar issues, feel free to share. Collaboration is key! 🤝", "utterranceID": "20270114-8-fe277"}, "Reactions": []}, "ThreadReplies": [], "id": "20270114-8-fe277"}
